if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !count <text>');
const text = argumentName;
const chars = text.length;
const charsNoSpaces = text.replace(/\s/g, '').length;
const words = text.trim().split(/\s+/).filter(w => w.length > 0).length;
const lines = text.split('\n').length;
const sentences = text.split(/[.!?]+/).filter(s => s.trim().length > 0).length;
await sendTrackedMessage(sock, remoteJid, `📊 Text Stats:\n\nCharacters: ${chars}\nCharacters (no spaces): ${charsNoSpaces}\nWords: ${words}\nLines: ${lines}\nSentences: ${sentences}`);
